css:
.emotionsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2f3b30;
    background: radial-gradient(circle at 12% 0%, #f4f9ee 0%, #eaf3e0 55%, #e2eed6 100%);
    border-radius: 18px;
}

.emotionsim-container * {
    box-sizing: border-box;
}

.emotionsim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #2f6b3e 0%, #4f9a52 55%, #7bbf6a 100%);
    color: #f4fbef;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #3b7a47;
    box-shadow: 0 12px 30px rgba(47, 107, 62, 0.28);
}

.emotionsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.emotionsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #fff4d6;
    background: rgba(255, 244, 214, 0.18);
    border: 1px solid rgba(255, 244, 214, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.emotionsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #eef7e6;
}

.emotionsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #4a5a48;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.emotionsim-period-counter #currentDay,
.emotionsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #2f6b3e;
}

.emotionsim-round-name {
    background: rgba(47, 107, 62, 0.12);
    color: #2f6b3e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.emotionsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a85b15;
    background: rgba(228, 138, 41, 0.14);
    border: 1px solid rgba(228, 138, 41, 0.34);
    padding: 4px 12px;
    border-radius: 999px;
}

.emotionsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.emotionsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #dce8ce;
    box-shadow: 0 6px 16px rgba(47, 107, 62, 0.10);
    border-top: 4px solid #7bbf6a;
}

.emotionsim-card-behavior { border-top-color: #2f8f4e; }
.emotionsim-card-regulation { border-top-color: #3d8bbf; }
.emotionsim-card-message { border-top-color: #c9942b; }
.emotionsim-card-resistance { border-top-color: #d4663a; }

.emotionsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6c7d68;
}

.emotionsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #243024;
    font-variant-numeric: tabular-nums;
}

.emotionsim-card-behavior .emotionsim-value { color: #2f8f4e; }
.emotionsim-card-regulation .emotionsim-value { color: #3d8bbf; }
.emotionsim-card-message .emotionsim-value { color: #c9942b; }
.emotionsim-card-resistance .emotionsim-value { color: #d4663a; }

.emotionsim-sublabel {
    font-size: 0.76rem;
    color: #7c8c78;
    line-height: 1.35;
}

.emotionsim-card-behavior.emotionsim-behavior-hit { border-top-color: #1f7a3e; background: #f1faf0; }
.emotionsim-card-behavior.emotionsim-behavior-hit .emotionsim-value { color: #1f7a3e; }

.emotionsim-card-resistance.emotionsim-resistance-high { border-top-color: #c23b1f; }
.emotionsim-card-resistance.emotionsim-resistance-high .emotionsim-value { color: #c23b1f; }
.emotionsim-card-resistance.emotionsim-resistance-low { border-top-color: #2f8f4e; }
.emotionsim-card-resistance.emotionsim-resistance-low .emotionsim-value { color: #2f8f4e; }

.emotionsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #fbf6ea;
    border: 1px solid #ecdcb8;
    color: #6a5a32;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.emotionsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #a85b15;
}

.emotionsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #4f9a52;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(47, 107, 62, 0.10);
}

.emotionsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.emotionsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #243024;
    margin-bottom: 6px;
}

.emotionsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #43523f;
}

.emotionsim-briefing-text strong { color: #2f8f4e; }
.emotionsim-briefing-text em { color: #a85b15; font-style: italic; }

.emotionsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #dce8ce;
    box-shadow: 0 6px 16px rgba(47, 107, 62, 0.10);
}

.emotionsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #243024;
    border-bottom: 2px solid #e4eed8;
    padding-bottom: 8px;
}

.emotionsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3a4a37;
    margin: 14px 0 6px;
}

.emotionsim-container select,
.emotionsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c5d8b4;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbfdf8;
    color: #2f3b30;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.emotionsim-container select:focus,
.emotionsim-container input[type="number"]:focus {
    outline: none;
    border-color: #4f9a52;
    box-shadow: 0 0 0 3px rgba(79, 154, 82, 0.18);
}

.emotionsim-container select option {
    background-color: #ffffff;
    color: #2f3b30;
}

.emotionsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #4f9a52;
}

.emotionsim-range-readout,
.emotionsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #5c6c58;
    margin-top: 4px;
}

.emotionsim-range-readout span:last-child,
.emotionsim-alloc-readout span:nth-child(2) {
    color: #2f8f4e;
    font-weight: 800;
}

.emotionsim-hint {
    font-size: 0.8rem;
    color: #7c8c78;
    margin-top: 4px;
    line-height: 1.4;
}

.emotionsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.emotionsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6faf0;
    border: 1px solid #d9e7c8;
    border-radius: 9px;
    padding: 8px 12px;
}

.emotionsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #3a4a37;
}

.emotionsim-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.emotionsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.emotionsim-container .btn-primary {
    background: linear-gradient(135deg, #2f6b3e 0%, #5cab5d 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(47, 107, 62, 0.30);
}

.emotionsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.emotionsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c5d8b4;
    color: #5c6c58;
    background: transparent;
}

.emotionsim-coach {
    background: linear-gradient(160deg, #fbf6ea 0%, #f5f0e1 100%);
    color: #4a4230;
    border: 1px solid #ecdcb8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(168, 91, 21, 0.10);
}

.emotionsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #a85b15;
    margin-bottom: 8px;
}

.emotionsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.emotionsim-coach-body strong { color: #2f8f4e; }
.emotionsim-coach-body em { color: #a85b15; font-style: italic; }

.emotionsim-history,
.emotionsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #dce8ce;
    box-shadow: 0 6px 16px rgba(47, 107, 62, 0.10);
}

.emotionsim-history h3,
.emotionsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #243024;
}

.emotionsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4a37;
}

.emotionsim-container table#usfHistoryTable th {
    background: #eef6e4;
    color: #2f6b3e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d9e7c8;
}

.emotionsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e7efdc;
    color: #43523f;
}

.emotionsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7fbf2;
}

.emotionsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .emotionsim-container {
        padding: 14px;
    }
    .emotionsim-header h1 {
        font-size: 1.7rem;
    }
    .emotionsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .emotionsim-value {
        font-size: 2rem;
    }
    .emotionsim-clock {
        margin-left: 0;
    }
    .emotionsim-period-counter {
        font-size: 0.88rem;
    }
    .emotionsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .emotionsim-alloc-row {
        flex-wrap: wrap;
    }
    .emotionsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .emotionsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion-message card (appended; self-contained, green) */
.emotionsim-cm { background:#f3f8f3; color:#243024; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(36,48,36,0.18); }
.emotionsim-cm-head { text-align:center; border-bottom:1px solid #cfe0cf; padding-bottom:14px; margin-bottom:16px; }
.emotionsim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#2f6b3e; font-weight:700; }
.emotionsim-cm-scorewrap { margin:8px 0 2px; }
.emotionsim-cm-score { font-size:52px; font-weight:800; color:#2f8f4e; line-height:1; }
.emotionsim-cm-score-max { font-size:20px; color:#84997f; font-weight:600; }
.emotionsim-cm-grade { font-size:19px; font-weight:700; color:#243024; margin-top:4px; }
.emotionsim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.emotionsim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.emotionsim-cm-met { background:#cce7d3; color:#1f6b3b; }
.emotionsim-cm-fail { background:#f3ddd2; color:#a4552a; }
.emotionsim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.emotionsim-cm-metric { background:#e6efe6; border-radius:10px; padding:12px 16px; min-width:96px; text-align:center; }
.emotionsim-cm-metric-val { font-size:22px; font-weight:800; color:#243024; }
.emotionsim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#2f6b3e; margin-top:3px; }
.emotionsim-cm-insights { background:#e6efe6; border-radius:10px; padding:14px 18px; }
.emotionsim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#2f6b3e; font-weight:700; margin-bottom:8px; }
.emotionsim-cm-insights ul { margin:0; padding-left:18px; }
.emotionsim-cm-insights li { font-size:14px; line-height:1.5; color:#2b3a2b; margin-bottom:7px; }

