(function() {
    'use strict';

    class EmotionAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Leading Change with Emotion`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Hanseatic Naturkost GmbH).
            this.START_BEHAVIOR = 22;     // % who changed any behavior (value-action gap)
            this.TARGET_BEHAVIOR = 50;    // board target — participation in ≥1 action
            this.BUDGET = 600;            // EUR 600k engagement budget, expressed in thousands
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    behavior: 22,            // behavior-change rate (%), headline KPI
                    regulation: 40,          // emotion-regulation score (0–100)
                    message: 35,             // message-effectiveness index (0–100)
                    resistance: 55,          // works-council / cynicism resistance risk (lower better)
                    budgetUsed: 0,           // EUR k of engagement budget committed
                    overPromised: false,     // hollow job-security guarantee made
                    oneOff: false,           // bought a spike with no persistence mechanism
                    fearReached: false,      // defaulted to a fear/guilt frame on anxious staff
                    behaviorHistory: [22],
                    regulationHistory: [40],
                    messageHistory: [35],
                    resistanceHistory: [55],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the CLASSIC ERRORS so a blind
                // click-through cannot auto-win.
                state.decisions = {
                    problem: `info`,
                    production: `fear`,
                    office: `guiltfatigue`,
                    council: `fear`,
                    frame: `fear`,
                    segment: `uniform`,
                    risk: `none`,
                    intensity: 50,
                    objection1: `roadmap`,
                    objection2: `overpromise`,
                    objection3: `moreguilt`,
                    posture: 50,
                    champions: 100,
                    dashboard: 100,
                    quickwins: 100,
                    managers: 100,
                    gamified: 200,
                    persistence: `oneoff`,
                    recognition: `prizes`
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const pb = document.getElementById(`problemInput`);
                const pr = document.getElementById(`productionInput`);
                const of = document.getElementById(`officeInput`);
                const cl = document.getElementById(`councilInput`);
                if (pb) decisions.problem = pb.value;
                if (pr) decisions.production = pr.value;
                if (of) decisions.office = of.value;
                if (cl) decisions.council = cl.value;
            } else if (round === 2) {
                const fr = document.getElementById(`frameInput`);
                const sg = document.getElementById(`segmentInput`);
                const rk = document.getElementById(`riskInput`);
                const it = document.getElementById(`intensityInput`);
                if (fr) decisions.frame = fr.value;
                if (sg) decisions.segment = sg.value;
                if (rk) decisions.risk = rk.value;
                if (it) decisions.intensity = parseInt(it.value, 10);
                if (!Number.isFinite(decisions.intensity) || decisions.intensity < 0 || decisions.intensity > 100) {
                    warn(`warn_intensity_range`); return false;
                }
            } else if (round === 3) {
                const o1 = document.getElementById(`objection1Input`);
                const o2 = document.getElementById(`objection2Input`);
                const o3 = document.getElementById(`objection3Input`);
                const ps = document.getElementById(`postureInput`);
                if (o1) decisions.objection1 = o1.value;
                if (o2) decisions.objection2 = o2.value;
                if (o3) decisions.objection3 = o3.value;
                if (ps) decisions.posture = parseInt(ps.value, 10);
                if (!Number.isFinite(decisions.posture) || decisions.posture < 0 || decisions.posture > 100) {
                    warn(`warn_posture_range`); return false;
                }
            } else if (round === 4) {
                const ch = document.getElementById(`championsInput`);
                const db = document.getElementById(`dashboardInput`);
                const qw = document.getElementById(`quickwinsInput`);
                const mg = document.getElementById(`managersInput`);
                const gm = document.getElementById(`gamifiedInput`);
                const pe = document.getElementById(`persistenceInput`);
                const rc = document.getElementById(`recognitionInput`);
                if (ch) decisions.champions = parseFloat(ch.value);
                if (db) decisions.dashboard = parseFloat(db.value);
                if (qw) decisions.quickwins = parseFloat(qw.value);
                if (mg) decisions.managers = parseFloat(mg.value);
                if (gm) decisions.gamified = parseFloat(gm.value);
                if (pe) decisions.persistence = pe.value;
                if (rc) decisions.recognition = rc.value;
                const parts = [decisions.champions, decisions.dashboard, decisions.quickwins, decisions.managers, decisions.gamified];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(parts.reduce((a, b) => a + b, 0));
                if (total !== this.BUDGET) {
                    warn(`warn_alloc_total`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let behaviorDelta = 0, regulationDelta = 0, messageDelta = 0, resistanceDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the emotional landscape (Common Error 1: information deficit).
                switch (d.problem) {
                    case `emotion`: messageDelta += 8; regulationDelta += 6; resistanceDelta -= 6; coachKey = `coach_r1_emotion`; break;
                    case `info`: messageDelta -= 6; resistanceDelta += 5; coachKey = `coach_r1_info`; break;
                    case `opposition`: regulationDelta -= 6; resistanceDelta += 8; coachKey = `coach_r1_opposition`; break;
                }

                // Correctly naming the dominant emotion per segment sharpens the later frame.
                let mapped = 0;
                if (d.production === `fear`) { mapped++; regulationDelta += 4; } else { messageDelta -= 3; resistanceDelta += 3; }
                if (d.office === `guiltfatigue`) { mapped++; messageDelta += 4; } else { messageDelta -= 3; }
                if (d.council === `fear`) { mapped++; resistanceDelta -= 6; regulationDelta += 3; }
                else { resistanceDelta += 8; coachKey = `coach_r1_routearound`; }

                if (mapped === 3 && d.problem === `emotion`) { messageDelta += 6; resistanceDelta -= 4; coachKey = `coach_r1_sharp`; }

                summaryKey = (d.problem === `emotion` && mapped >= 2) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Choose the communication frame (Common Error 2: default to fear/guilt).
                const inten = d.intensity / 100;
                const tailored = (d.segment === `tailor`);

                switch (d.frame) {
                    case `hope`:
                        // Durable: builds efficacy. Slower, so lower instant spike but real behavior.
                        messageDelta += 14; behaviorDelta += 5; resistanceDelta -= 8;
                        coachKey = `coach_r2_hope`;
                        break;
                    case `pride`:
                        // Identity frame — strong for a "clean origin" company, tolerates intensity.
                        messageDelta += 11; behaviorDelta += 4; resistanceDelta -= 5;
                        coachKey = `coach_r2_pride`;
                        break;
                    case `fear`:
                        // Spikes attention, but deepens avoidance in the anxious segment.
                        messageDelta += 6 - inten * 12; behaviorDelta -= 2; resistanceDelta += 6 + inten * 6;
                        ds.fearReached = true;
                        coachKey = `coach_r2_fear`;
                        break;
                    case `guilt`:
                        // Hits the 34% who are already guilt-fatigued — diminishing returns.
                        messageDelta += 4 - inten * 11; behaviorDelta -= 2; resistanceDelta += 4 + inten * 4;
                        ds.fearReached = true;
                        coachKey = `coach_r2_guilt`;
                        break;
                }

                // Tailoring the frame to the anxious production segment protects them.
                if (tailored) {
                    messageDelta += 7; resistanceDelta -= 6;
                    if (d.frame === `fear` || d.frame === `guilt`) {
                        // A tailored hope frame for production cushions a threat-heavy headline.
                        resistanceDelta -= 5; behaviorDelta += 2; ds.fearReached = false;
                    }
                } else if (d.frame === `fear` || d.frame === `guilt`) {
                    resistanceDelta += 5; coachKey = `coach_r2_uniformthreat`;
                }

                // Naming the emotional risk = leadership awareness.
                switch (d.risk) {
                    case `namedfear`: messageDelta += 5; resistanceDelta -= 4; break;
                    case `slow`: if (d.frame === `hope` || d.frame === `pride`) { behaviorDelta += 3; messageDelta += 3; } break;
                    case `none`: messageDelta -= 4; resistanceDelta += 4; if (coachKey === `coach_default`) coachKey = `coach_r2_norisk`; break;
                }

                // Pure intensity on a hope/pride frame helps a little; on fear/guilt it hurts (handled above).
                if ((d.frame === `hope` || d.frame === `pride`) && d.intensity >= 60) messageDelta += 3;

                summaryKey = ((d.frame === `hope` || d.frame === `pride`) && d.risk !== `none`) ? `sum_r2_good` :
                             ((d.frame === `fear` || d.frame === `guilt`) ? `sum_r2_threat` : `sum_r2_weak`);
            } else if (round === 3) {
                // Manage the anxious team (Common Errors 3 & 4: dismiss feelings, hollow reassurance).
                // Objection 1 — validate-before-reframe.
                switch (d.objection1) {
                    case `validate`: regulationDelta += 12; resistanceDelta -= 8; coachKey = `coach_r3_validate`; break;
                    case `roadmap`: regulationDelta -= 6; resistanceDelta += 8; coachKey = `coach_r3_spreadsheet`; break;
                    case `dismiss`: regulationDelta -= 10; resistanceDelta += 12; coachKey = `coach_r3_dismiss`; break;
                }

                // Objection 2 — credible vs hollow reassurance.
                switch (d.objection2) {
                    case `credible`: regulationDelta += 10; resistanceDelta -= 6; behaviorDelta += 2; break;
                    case `overpromise`: regulationDelta += 4; resistanceDelta += 8; ds.overPromised = true; coachKey = `coach_r3_overpromise`; break;
                    case `deflect`: regulationDelta -= 8; resistanceDelta += 6; coachKey = `coach_r3_deflect`; break;
                }

                // Objection 3 — restore efficacy to a guilt-fatigued audience.
                switch (d.objection3) {
                    case `efficacy`: regulationDelta += 8; messageDelta += 6; resistanceDelta -= 5; break;
                    case `moreguilt`: regulationDelta -= 6; messageDelta -= 6; resistanceDelta += 5; if (coachKey === `coach_default`) coachKey = `coach_r3_moreguilt`; break;
                    case `data`: messageDelta -= 4; resistanceDelta += 3; break;
                }

                // Posture: weight on validating emotion before reframing.
                if (d.posture >= 60) { regulationDelta += 5; resistanceDelta -= 4; }
                else if (d.posture <= 25) { regulationDelta -= 5; resistanceDelta += 6; if (coachKey === `coach_default`) coachKey = `coach_r3_rational`; }

                if (d.objection1 === `validate` && d.objection2 === `credible` && d.objection3 === `efficacy`) coachKey = `coach_r3_playbook`;

                summaryKey = (d.objection1 === `validate` && d.objection2 === `credible`) ? `sum_r3_good` :
                             (ds.overPromised ? `sum_r3_hollow` : `sum_r3_weak`);
            } else if (round === 4) {
                // Design the engagement initiative (Common Error 5: one-off campaign).
                const ch = d.champions, db = d.dashboard, qw = d.quickwins, mg = d.managers, gm = d.gamified;
                spend = ch + db + qw + mg + gm;

                // Effectiveness of spend depends on the foundation laid in R1–R3.
                // message-fit and regulation amplify uptake; high resistance damps it.
                const fit = ds.message / 100;          // 0–1 frame-to-emotion fit
                const reg = ds.regulation / 100;        // 0–1 emotion-regulation
                const foundation = 0.55 + 0.30 * fit + 0.30 * reg;   // ~0.55–1.15 multiplier
                const resistDrag = 1 - (Math.max(0, ds.resistance - 30) / 100) * 0.6;  // high resistance bleeds uptake

                // Per-lever uptake yield per EUR k (durable levers worth more, gamified spiky).
                // Returns in behavior-change points; champions/dashboard/quickwins/managers persist,
                // gamified is front-loaded and decays without a feedback loop.
                let raw =
                    ch * 0.060 +     // peer champions — social proof, persistent
                    db * 0.050 +     // dashboard — collective efficacy feedback loop
                    qw * 0.045 +     // visible quick-wins — proof action is possible
                    mg * 0.048 +     // manager conversations — local control, answers fear
                    gm * 0.030;      // gamified — high gross but heavily decayed below

                // Diversification: relying on a single lever (esp. gamified) caps the gain.
                const levers = [ch, db, qw, mg, gm];
                const maxLever = Math.max.apply(null, levers);
                const concentration = maxLever / this.BUDGET;     // 0.2 even split … 1.0 all-in
                const diversifyFactor = concentration > 0.5 ? (1 - (concentration - 0.5) * 0.7) : 1;

                // Persistence design: a one-off spike decays; durable design holds it.
                let persistFactor = 1;
                if (d.persistence === `durable` && (ch + db) >= 200) {
                    persistFactor = 1.15; resistanceDelta -= 4;
                } else if (d.persistence === `oneoff` || gm > (ch + db + qw + mg)) {
                    persistFactor = 0.62; ds.oneOff = true; coachKey = `coach_r4_oneoff`;
                }

                // Recognition: ongoing pride/identity reinforcement vs one-time prizes.
                if (d.recognition === `recognition`) { behaviorDelta += 3; resistanceDelta -= 3; }
                else { messageDelta -= 2; if (!ds.oneOff && coachKey === `coach_default`) coachKey = `coach_r4_prizes`; }

                behaviorDelta += raw * foundation * resistDrag * diversifyFactor * persistFactor;

                // Neglecting feedback loop / champions entirely is fragile even if uptake spikes.
                if ((ch + db) <= 50) { resistanceDelta += 5; if (coachKey === `coach_default`) coachKey = `coach_r4_nofeedback`; }
                else if (d.persistence === `durable` && (ch + db) >= 250 && d.recognition === `recognition`) coachKey = `coach_r4_durable`;

                if (coachKey === `coach_default`) coachKey = `coach_r4_mixed`;

                summaryKey = (d.persistence === `durable` && (ch + db) >= 200) ? `sum_r4_good` :
                             (ds.oneOff ? `sum_r4_oneoff` : `sum_r4_weak`);
            }

            // Resource accounting: engagement budget committed (only metered in R4).
            ds.budgetUsed = Math.min(this.BUDGET, Math.round(ds.budgetUsed + spend));

            // Apply deltas, clamped. behavior is a % (can exceed start), others 0–100.
            ds.behavior = Math.max(0, Math.min(100, Math.round((ds.behavior + behaviorDelta) * 10) / 10));
            ds.regulation = Math.max(0, Math.min(100, Math.round(ds.regulation + regulationDelta)));
            ds.message = Math.max(0, Math.min(100, Math.round(ds.message + messageDelta)));
            ds.resistance = Math.max(0, Math.min(100, Math.round(ds.resistance + resistanceDelta)));

            ds.behaviorHistory.push(ds.behavior);
            ds.regulationHistory.push(ds.regulation);
            ds.messageHistory.push(ds.message);
            ds.resistanceHistory.push(ds.resistance);

            // v1.1.0: persist composite for instructor gradebook (results_utils.php Ruta 1).
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                behavior: ds.behavior,
                behaviorDelta: Math.round(behaviorDelta * 10) / 10,
                regulation: ds.regulation,
                regulationDelta: Math.round(regulationDelta),
                message: ds.message,
                messageDelta: Math.round(messageDelta),
                resistance: ds.resistance,
                resistanceDelta: Math.round(resistanceDelta),
                budgetUsed: ds.budgetUsed,
                overPromised: ds.overPromised,
                oneOff: ds.oneOff,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

