                const bar = document.querySelector(`.emotionsim-alloc-readout`);
                if (bar) bar.style.color = (total !== self.BUDGET) ? `#d4663a` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

