        _composite(ds) {
            // v1.1.0 single source of truth - verbatim v1.0.0 formula (scoring unchanged).
            const behavior = Math.round(ds.behavior);
            const regulation = Math.round(ds.regulation);
            const message = Math.round(ds.message);
            const resistance = Math.round(ds.resistance);
            const behaviorScore = Math.max(0, Math.min(100, (behavior / this.TARGET_BEHAVIOR) * 70));
            return Math.round(behaviorScore * 0.42 + regulation * 0.22 + message * 0.18 + (100 - resistance) * 0.18);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const behavior = Math.round(ds.behavior);
            const regulation = Math.round(ds.regulation);
            const message = Math.round(ds.message);
            const resistance = Math.round(ds.resistance);

            // Composite: hitting the behavior target dominates, then regulation,
            // message fit, and low resistance.
            const behaviorScore = Math.max(0, Math.min(100, (behavior / this.TARGET_BEHAVIOR) * 70));
            const composite = this._composite(ds);

            const hitTarget = behavior >= this.TARGET_BEHAVIOR;
            const durable = !ds.oneOff && regulation >= 55 && resistance <= 45;
            const credible = !ds.overPromised && regulation >= 55;
            const backfired = ds.fearReached && resistance >= 60;

            let performanceKey = `grade_unmoved`;
            if (hitTarget && durable && credible && composite >= 75) performanceKey = `grade_durable`;
            else if (hitTarget && durable) performanceKey = `grade_builttolast`;
            else if (hitTarget && ds.oneOff) performanceKey = `grade_spike`;
            else if (backfired) performanceKey = `grade_backfired`;
            else if (resistance >= 70) performanceKey = `grade_hardened`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const performance = window.mySimulation.t(performanceKey);
            const met = hitTarget && durable && credible && composite >= 75;

            const insights = [];
            if (hitTarget && durable && credible) insights.push(window.mySimulation.t(`insight_durable`));
            else if (backfired) insights.push(window.mySimulation.t(`insight_backfire`));
            else if (ds.oneOff && hitTarget) insights.push(window.mySimulation.t(`insight_spike`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (!hitTarget) insights.push(window.mySimulation.t(`insight_belowtarget`));
            else insights.push(window.mySimulation.t(`insight_attarget`));
            if (ds.overPromised) insights.push(window.mySimulation.t(`insight_overpromise`));
            if (ds.fearReached) insights.push(window.mySimulation.t(`insight_fearframe`));
            if (resistance <= 30 && regulation >= 60) insights.push(window.mySimulation.t(`insight_trusted`));

            return {
                behavior: behavior,
                regulation: regulation,
                message: message,
                resistance: resistance,
                hitTarget: hitTarget,
                durable: durable,
                credible: credible,
                backfired: backfired,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="emotionsim-cm-badge ` + (s.met ? `emotionsim-cm-met` : `emotionsim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.hitTarget === false) badges.push(`<span class="emotionsim-cm-badge emotionsim-cm-fail">` + t(`cm_fail_target`) + `</span>`);
            if (s.durable === false) badges.push(`<span class="emotionsim-cm-badge emotionsim-cm-fail">` + t(`cm_fail_durable`) + `</span>`);
            if (s.backfired) badges.push(`<span class="emotionsim-cm-badge emotionsim-cm-fail">` + t(`cm_fail_backfire`) + `</span>`);
            const kpi = (label, val) => `<div class="emotionsim-cm-metric"><div class="emotionsim-cm-metric-val">` + val + `</div><div class="emotionsim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_behavior`), (s.behavior != null ? Math.round(s.behavior) : 0) + `%`)
                + kpi(t(`cm_regulation`), (s.regulation != null ? Math.round(s.regulation) : 0))
                + kpi(t(`cm_message`), (s.message != null ? Math.round(s.message) : 0))
                + kpi(t(`cm_resistance`), (s.resistance != null ? Math.round(s.resistance) : 0))
                + kpi(t(`cm_index`), score + `/100`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="emotionsim-cm">`
                + `<div class="emotionsim-cm-head"><div class="emotionsim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="emotionsim-cm-scorewrap"><span class="emotionsim-cm-score">` + score + `</span><span class="emotionsim-cm-score-max">/100</span></div>`
                + `<div class="emotionsim-cm-grade">` + grade + `</div>`
                + `<div class="emotionsim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="emotionsim-cm-metrics">` + kpis + `</div>`
                + `<div class="emotionsim-cm-insights"><div class="emotionsim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

